type:
∀ {m i : ℕ} (P : Fin m → Prop) [inst : DecidablePred P],
  have S := fun (j : ℕ) => {e : Fin m | ↑e + 1 < j ∧ P e};
  (S (i + 1)).card = (S i).card ∨ (S (i + 1)).card = (S i).card + 1

∀ {J : Type u_1} [inst : Fintype J] [inst_1 : DecidableEq J] {k : ℕ} (p : J → TimeProfile.Simplex k) (I : Finset J)
  (chi : ℝ) (w : J → Fin k),
  RiffleUpperV2.FirstMoment.exceptionalPositions p I chi w = {j ∈ I | TimeProfile.prob (p j) (w j) < chi}

∀ {k d : ℕ} {v w : RiffleUpperV2.Prefix k d} {Q : RiffleUpperV2.Prefix k d → Prop}
  (hex : ∃ (m : ℕ) (hm : m ≤ ↑w.fst), ↑v.fst ≤ m ∧ (Q (RiffleUpperV2.Localization.takePrefix w m hm) ∨ m = d))
  (u : RiffleUpperV2.Prefix k d), Nat.find hex ≤ ↑u.fst → ↑u.fst < Nat.find hex → False

∀ {k n : ℕ} {count : ℕ → Fin k → ℕ} {sum_count : ∀ (j : ℕ), ∑ d : Fin k, count j d = n} {count_1 : ℕ → Fin k → ℕ}
  {sum_count_1 : ∀ (j : ℕ), ∑ d : Fin k, count_1 j d = n},
  { count := count, sum_count := sum_count } = { count := count_1, sum_count := sum_count_1 } → count = count_1

∀ (p : RiffleLowerV2.Thinning.Compat.HypergeomParams),
  RiffleUpperV2.Anchor.swappedParams p =
    { population := p.population, marked := p.draws, draws := p.marked, marked_le := ⋯, draws_le := ⋯ }

∀ {α : Type u_1} (V A : Finset α) (m : ℕ) (hA : A ⊆ V) (hm : m ≤ V.card),
  RiffleLowerV2.Thinning.Compat.samplingParams V A m hA hm =
    { population := V.card, marked := A.card, draws := m, marked_le := ⋯, draws_le := hm }

∀ {k n d N : ℕ} {cuts : RiffleUpperV2.Cuts k n d} {R : Finset (Fin n)} {v : RiffleUpperV2.Prefix k d} {δ : ℝ}
  {x : RiffleUpperV2.Prefix k d},
  RiffleUpperV2.Localization.ProperStable N cuts R v δ x → ¬RiffleUpperV2.Localization.Stops N cuts R v δ v

∀ {k d : ℕ} (default : Fin d → Fin k) (x : RiffleUpperV2.Prefix k d),
  RiffleUpperV2.FirstMoment.boundaryExceptions default x =
    {j : Fin d | ↑j + 1 < ↑x.fst ∧ RiffleUpperV2.FirstMoment.completePrefix default x j ≠ default j}
